    /** The retired map numbered {@code map}, or null. */
    static SiteMaps.Site byMap(int map) {
        for (SiteMaps.Site site : ALL) {
            if (site.map() == map) {
                return site;
            }
        }
        return null;
    }

    static int[] edges(String text) {
        String[] parts = text.split(",");
        int[] out = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            out[i] = Integer.parseInt(parts[i]);
        }
        return out;
    }

    static int[][] points(String text) {
        String[] parts = text.split(";");
        int[][] out = new int[parts.length][];
        for (int i = 0; i < parts.length; i++) {
            String[] p = parts[i].split(",");
            out[i] = new int[] {Integer.parseInt(p[0]), Integer.parseInt(p[1]), Integer.parseInt(p[2])};
        }
        return out;
    }
